$s=new Settings($db,'own-paper-office');$f=new Finance($db,'own-paper-treasurer');$r=new Registry($db,'own-paper-office');$docs=new Documents($db,'own-paper-treasurer');$key=static fn()=>bin2hex(random_bytes(16));
$s->save('club',array_replace(SettingsSchema::defaults('club'),['name'=>'Own legal invoice issuer','street'=>'Own legal street 1','postcode'=>'23456','city'=>'Own legal town']),0);
$account=$f->createAccount('Own invoice bank','offline','0','2026-01-01');$s->save('bank',array_replace(SettingsSchema::defaults('bank'),['account_id'=>$account,'holder'=>'Own legal invoice issuer','iban'=>'DE89370400440532013000']),0);
