$issuer=new ContributionInvoices($db,'own-paper-treasurer');$oldEntry=$f->createEntry($entryInput,$key());$oldIssued=$issuer->issue($oldEntry);$oldFile=$docs->file($oldIssued['document_id']);$oldSnapshot=json_decode($oldFile['snapshot'],true,512,JSON_THROW_ON_ERROR);
