$tables=$db->query('SHOW TABLES')->fetchAll(PDO::FETCH_COLUMN);$before=ownOriginalDatabaseHash($db,$tables);$normal=$outgoing->preview($id);$normalPdf=DocumentPreview::pdf($normal);$normalReadOnly=ownOriginalDatabaseHash($db,$tables)===$before;
$letter=DocumentPreview::letter($s,['recipient'=>'Own literal recipient','subject'=>'Own sender policy','body'=>'Own actual letter','date'=>'2026-10-21']);
$malformed=$paper['data'];$malformed['logo']=$signature['id'];$q=$db->prepare("UPDATE club_settings SET payload=? WHERE club_id='own-paper-finance' AND section='paper'");$q->execute([json_encode($malformed,JSON_THROW_ON_ERROR)]);
$before=ownOriginalDatabaseHash($db,$tables);$outgoingPrivate=false;$outgoingCode=0;try{$doc=$outgoing->preview($id);$outgoingPrivate=base64_decode($doc['assets']['logo']['base64']??'',true)===$signature['bytes']&&str_starts_with(DocumentPreview::pdf($doc),'%PDF-');}catch(DomainException$e){$outgoingCode=$e->getCode();}$outgoingReadOnly=ownOriginalDatabaseHash($db,$tables)===$before;
$nextEntry=$f->createEntry(array_replace($entryInput,['description'=>'Own next contribution']),$key());$before=ownOriginalDatabaseHash($db,$tables);$contributionPrivate=false;$contributionCode=0;try{$new=$issuer->issue($nextEntry);$newSnapshot=json_decode($docs->file($new['document_id'])['snapshot'],true,512,JSON_THROW_ON_ERROR);$contributionPrivate=base64_decode($newSnapshot['assets']['logo']['base64']??'',true)===$signature['bytes'];}catch(DomainException$e){$contributionCode=$e->getCode();}$contributionReadOnly=ownOriginalDatabaseHash($db,$tables)===$before;
$before=ownOriginalDatabaseHash($db,$tables);$oldPreserved=$issuer->issue($oldEntry)===$oldIssued&&$docs->file($oldIssued['document_id'])===$oldFile&&ownOriginalDatabaseHash($db,$tables)===$before;

$check(!Permissions::actor($db,'own-paper-treasurer')['settings_access']&&$normalReadOnly&&str_starts_with($normalPdf,'%PDF-')&&base64_decode($normal['assets']['logo']['base64'],true)===$normalLogo['bytes'],'actual finance-only invoice preview retains its legitimate logo without borrowing general settings rights or writing any business row');
