$check($refuse(fn()=>$outgoing->preview($id),503),'actual outgoing preview rejects bytes that differ from the selected legitimate logo checksum without silently replacing the source or writing any row');
$check($refuse(fn()=>$issuer->issue($nextEntry),503),'actual contribution issuance rejects damaged legitimate logo bytes before storing any invoice document history or notification');
$damage->execute([$normalLogo['bytes'],$paper['data']['logo']]);$before=ownOriginalDatabaseHash($db,$tables);$again=$outgoing->preview($id);$check($again['paper']['sender_name']==='Own legal invoice issuer'&&base64_decode($again['assets']['logo']['base64'],true)===$normalLogo['bytes']&&ownOriginalDatabaseHash($db,$tables)===$before,'return of the exact legitimate logo restores the same finance-only read without general rights or any invented replacement file');
$new=$issuer->issue($nextEntry);$newFile=$docs->file($new['document_id']);$newSnapshot=json_decode($newFile['snapshot'],true,512,JSON_THROW_ON_ERROR);
$check($new['state']==='issued'&&$newSnapshot['paper']['sender_name']==='Own legal invoice issuer'&&base64_decode($newSnapshot['assets']['logo']['base64'],true)===$normalLogo['bytes']&&!isset($newSnapshot['assets']['signature'])&&$docs->file($oldIssued['document_id'])===$oldFile,'actual finance-only contribution issuance resumes with its genuine logo legal issuer and no private signature asset while preserving the earlier complete issued file');
$busyEntry=$f->createEntry(array_replace($entryInput,['description'=>'Own locked-logo contribution']),$key());$busyBefore=ownOriginalDatabaseHash($db,$tables);
$cfg=\Kulturhus\Native\TestSupport::config();$busyDb=new PDO('mysql:host='.$cfg['host'].';port='.$cfg['port'].';dbname='.$cfg['database'].';charset=utf8mb4',$cfg['username'],$cfg['password'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC,PDO::ATTR_EMULATE_PREPARES=>false]);$busyDb->beginTransaction();$busyDb->prepare('SELECT id FROM settings_assets WHERE club_id=? AND id=? FOR UPDATE')->execute(['own-paper-finance',$paper['data']['logo']]);
try{
 $db->beginTransaction();$started=microtime(true);$busy=$refuse(fn()=>$outgoing->preview($id),503);$caller=$db->inTransaction();$db->rollBack();
 $check($busy&&$caller&&microtime(true)-$started<2&&ownOriginalDatabaseHash($db,$tables)===$busyBefore,'actual independent logo row lock refuses an outgoing preview promptly with a retryable domain result and preserves its existing caller transaction and every complete row');
 $started=microtime(true);$busy=$refuse(fn()=>$issuer->issue($busyEntry),503);
 $check($busy&&!$db->inTransaction()&&microtime(true)-$started<2&&ownOriginalDatabaseHash($db,$tables)===$busyBefore,'actual independent logo row lock refuses contribution issuance promptly and rolls back its entire invoice transaction without a document or notification');
}finally{if($db->inTransaction())$db->rollBack();$busyDb->rollBack();}
